#include <bits/stdc++.h>
using namespace std;

map<long long, long long> h;

long long gao(long long n) {
    if (!h.count(n)) {
        long long t = 1;
        long long d = 2;
        while (d * d <= n) {
            if (n % d == 0) {
                t = max(t, max(gao(d), gao(n / d)));
            }
            d += 1;
        }
        h[n] = n + t;
    }
    return h[n];
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    h[1] = 1;
    long long n;
    if (!(cin >> n)) return 0;
    cout << gao(n) << '\n';
    return 0;
}

